UPDATE public.tender_calculation_settings s SET post_types = s.post_types || COALESCE((SELECT jsonb_agg(e.value) FROM jsonb_array_elements('[{"id":"00000000-0000-4000-8000-000000000029","name":"Huvudledning lägenhet","hours":3,"list_price":1200},{"id":"00000000-0000-4000-8000-000000000030","name":"Huvudledning lokal","hours":5,"list_price":2500},{"id":"00000000-0000-4000-8000-000000000031","name":"Fastighetscentral","hours":24,"list_price":25000},{"id":"00000000-0000-4000-8000-000000000032","name":"Armatur trapphus","hours":1,"list_price":900}]'::jsonb) e WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(s.post_types) p WHERE lower(p.value->>'name') = lower(e.value->>'name'))), '[]'::jsonb), example_values = true WHERE s.company_id='f9df621c-a4f6-4fd1-acff-a89a67d4aa9e';